const msg = $('Telegram Trigger').first().json.message;
const loc = msg.location;
return [{
  json: {
    userMessage: `I'm sharing my location: ${loc.latitude}, ${loc.longitude}\n\nUse the HTTP Tool to resolve the address via https://nominatim.openstreetmap.org/reverse?lat=${loc.latitude}&lon=${loc.longitude}&format=json&accept-language=de`
  }
}];

return [{
  json: {
    userMessage: 'I sent a media type that is not yet supported (sticker, video, etc).'
  }
}];

const msg = $('Telegram Trigger').first().json.message;
const chatId = String(msg.chat.id);
const userId = String(msg.from.id);
const source = 'telegram';
const sessionId = 'telegram:' + chatId;
const qualifiedUserId = 'telegram:' + userId;

function out(userMessage) {
  return [{ json: { userMessage, chatId, userId, sessionId, qualifiedUserId, source } }];
}

let userMessage = '';

// Check voice transcription result
try {
  const transcript = $('Transcribe Voice').first()?.json?.text;
  if (transcript) {
    return out('[Voice message] ' + transcript);
  }
} catch(e) {}

// Try to get file_ref from File Bridge upload
let fileRef = '';
try { fileRef = $('Save File Metadata').first()?.json?.file_ref || ''; } catch(e) {}

// Check photo (analyzed by OpenAI Vision)
try {
  const analysis = $('Analyze Photo').first();
  if (analysis) {
    let description = '';
    const j = analysis.json;
    if (Array.isArray(j)) {
      description = j[0]?.content?.[0]?.text || JSON.stringify(j);
    } else {
      description = j.text || j.content || JSON.stringify(j);
    }
    const caption = msg.caption || '';
    const refTag = fileRef ? ' | file_ref: ' + fileRef : '';
    userMessage = '[Photo' + refTag + ']\n' + description + (caption ? '\n\nUser caption: ' + caption : '');
    return out(userMessage);
  }
} catch(e) {}

// Check document (PDF text extracted by Extract PDF Text node)
try {
  const extracted = $('Extract PDF Text').first();
  if (extracted) {
    const filename = msg.document?.file_name || 'unknown';
    const pdfText = extracted.json.text || '';
    const refTag = fileRef ? ' | file_ref: ' + fileRef : '';
    userMessage = '[Document: ' + filename + refTag + ']\n\n' + pdfText + '\n\n' + (msg.caption || 'Please analyze this document.');
    return out(userMessage);
  }
} catch(e) {}

// Check location
try {
  const locMsg = $('Format Location').first()?.json?.userMessage;
  if (locMsg) {
    return out(locMsg);
  }
} catch(e) {}

// Check unsupported
try {
  const unsup = $('Unsupported Media').first()?.json?.userMessage;
  if (unsup) {
    return out(unsup);
  }
} catch(e) {}

// Default: text message
userMessage = msg.text || '';
return out(userMessage);

const raw = $input.first().json;
const message = raw.message || '';
const chatId = String(raw.chat_id || '');
// Strip 'telegram:' prefix if present to get raw numeric ID
const userId = String(raw.user_id || '').replace('telegram:', '');
const source = raw.source || 'scheduled_task';
const sessionId = 'telegram:' + chatId;
const qualifiedUserId = 'telegram:' + userId;

return [{ json: { userMessage: message, chatId, userId, sessionId, qualifiedUserId, source } }];

// Build system prompt from loaded context
const soul = $('Load Soul').all().map(i => i.json);
// Deduplicate: sequential node chaining causes cartesian product (6 soul × 6 agents = 36 items)
const agentsRaw = $('Load Agents Config').all().map(i => i.json);
const agents = [...new Map(agentsRaw.map(a => [a.key, a])).values()];
const user = $('Load User Profile').first()?.json || {};
// Deduplicate conversation history (36x duplicated due to upstream cartesian product)
const historyRaw = $('Load Conversation History').all().map(i => i.json);
const seenHist = new Set();
const history = historyRaw.filter(h => { const k = h.role + ':' + h.content; if (seenHist.has(k)) return false; seenHist.add(k); return true; });
const mergeData = $('Merge Input').first().json;
const userMessage = mergeData.userMessage || '';
const chatId = mergeData.chatId;
const userId = mergeData.userId;
const inputSource = mergeData.source || 'telegram';

// Build dynamic MCP server list from mcp_registry
const mcpRaw = $('Load MCP Servers').all().map(i => i.json);
const seenMcp = new Set();
const mcpServers = mcpRaw.filter(s => { if (!s.server_name || seenMcp.has(s.server_name)) return false; seenMcp.add(s.server_name); return true; });
let mcpServerList = '';
if (mcpServers.length > 0) {
  mcpServerList = '\n\n## Available MCP Skills:\n' + mcpServers.map(s => {
    const tools = Array.isArray(s.tools) ? s.tools.join(', ') : s.tools;
    return `- ${s.server_name}: ${s.mcp_url} (tools: ${tools})${s.description ? ' — ' + s.description : ''}`;
  }).join('\n');
}

// Inject dynamic server list into mcp_instructions (replace any static server section)
const agentText = agents.map(a => {
  if (a.key === 'mcp_instructions') {
    const cleaned = a.content.replace(/\n## (?:Available MCP (?:Servers|Skills)|Currently installed MCP Skills)[\s\S]*?(?=\n## |$)/, '');
    return `## ${a.key}\n${cleaned}${mcpServerList}`;
  }
  return `## ${a.key}\n${a.content}`;
}).join('\n\n');

// Build soul text
const soulText = soul.map(s => `## ${s.key}\n${s.content}`).join('\n\n');
const userText = user.display_name
  ? `Name: ${user.display_name} (${user.name})\nTimezone: ${user.timezone}\nKontext: ${user.context}\nPrefs: ${JSON.stringify(user.preferences)}\nSetup done: ${user.setup_done !== false ? 'true' : 'false'}`
  : 'Unbekannter User';

// Build conversation history
const historyText = history.reverse().map(h => `${h.role}: ${h.content}`).join('\n');

// Current date/time in user's timezone
const now = $now.setZone(user.timezone || 'UTC').toFormat('cccc, dd LLLL yyyy, HH:mm');

const scheduledHint = inputSource === 'scheduled_task' ? '\n\n# SCHEDULED TASK\nThis message is a scheduled task that the user set up earlier. Execute the instructions thoroughly and send the result. Start your response with a brief ⏰ note that this is a scheduled task result.' : '';

// Build active projects list (names only — content loaded on demand via Project Manager tool)
const projectsRaw = $('Load Active Projects').all().map(i => i.json);
const seenProj = new Set();
const activeProjects = projectsRaw.filter(p => { if (!p.name || seenProj.has(p.name)) return false; seenProj.add(p.name); return true; });
let projectsSection = '';
if (activeProjects.length > 0) {
  projectsSection = '\n\n# ACTIVE PROJECTS\n' + activeProjects.map(p => {
    const d = p.updated_at ? new Date(p.updated_at).toISOString().split('T')[0] : '';
    return `- ${p.name} (updated: ${d})`;
  }).join('\n') + '\nUse the Project Manager tool to read or update project details.';
}

// Insights — derived from nightly memory consolidation pattern extraction (n8n-claw v1.4 Hermes-Memory)
// Top-3 by importance, non-outdated. Empty section omitted entirely if no insights yet.
const insightsRaw = $('Load Insights').all().map(i => i.json);
const seenIns = new Set();
const insights = insightsRaw.filter(i => { if (!i || !i.content || seenIns.has(i.id)) return false; seenIns.add(i.id); return true; });
let insightsSection = '';
if (insights.length > 0) {
  insightsSection = '\n\n# WHAT YOU KNOW ABOUT THE USER (INSIGHTS)\nThese behavioral patterns were extracted from past conversations during nightly consolidation. Use them as context to shape your responses, but do NOT explicitly cite them ("I noticed you tend to..."). Let them inform your tone, pacing, and suggestions silently.\n' + insights.map(i => `- ${i.content}`).join('\n');
}

const systemPrompt = `# CURRENT TIME\n${now}\n\n# SOUL\n${soulText}\n\n# AGENT CONFIG\n${agentText}\n\n# USER PROFILE\n${userText}${insightsSection}${scheduledHint}${projectsSection}\n\n# RECENT CONVERSATION\n${historyText}`;

return [{
  json: {
    systemPrompt,
    userMessage,
    chatId: String(chatId),
    userId: String(userId),
    sessionId: mergeData.sessionId || `telegram:${chatId}`,
    qualifiedUserId: mergeData.qualifiedUserId || `telegram:${userId}`,
    source: inputSource,
    _webhookSource: mergeData._webhookSource || false,
    metadata: mergeData.metadata || {}
  }
}];

// Save conversation + daily log via PostgREST (avoids pg-promise $N escaping bug)
const bsp = $('Build System Prompt').first().json;
const userMessage = bsp.userMessage;
const assistantMessage = $('AI Agent').first().json.output;
const sessionId = bsp.sessionId;
const userId = bsp.userId;
const qualifiedUserId = bsp.qualifiedUserId;
const source = bsp.source || 'telegram';
const _webhookSource = bsp._webhookSource || false;
const metadata = bsp.metadata || {};

// Suppress heartbeat proactive-reminder skips: if the agent decided all open loops are trivial,
// it returns the literal '[SKIP]' marker. Drop the response entirely — no save, no notify.
if (typeof assistantMessage === 'string' && assistantMessage.trim() === '[SKIP]') {
  return [];
}

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const headers = { 'apikey': SUPABASE_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' };

// Save user + assistant messages
await helpers.httpRequest({ method: 'POST', url: `${SUPABASE_URL}/rest/v1/conversations`, headers, body: JSON.stringify({ session_id: sessionId, user_id: userId, role: 'user', content: userMessage }) });
await helpers.httpRequest({ method: 'POST', url: `${SUPABASE_URL}/rest/v1/conversations`, headers, body: JSON.stringify({ session_id: sessionId, user_id: userId, role: 'assistant', content: assistantMessage }) });

// Save daily log
await helpers.httpRequest({ method: 'POST', url: `${SUPABASE_URL}/rest/v1/memory_daily`, headers, body: JSON.stringify({ date: new Date().toISOString().split('T')[0], content: userMessage + ' → ' + assistantMessage, role: 'interaction', user_id: userId }) });

// Mark onboarding done if needed
const setupDone = $('Load User Profile').first()?.json?.setup_done;
if (setupDone === false) {
  await helpers.httpRequest({ method: 'PATCH', url: `${SUPABASE_URL}/rest/v1/user_profiles?user_id=eq.${encodeURIComponent(qualifiedUserId)}`, headers, body: JSON.stringify({ setup_done: true }) });
}

return [{ json: { saved: true, sessionId, _webhookSource, metadata } }];

let text = $('AI Agent').first().json.output || '';

// Strip [send_file: URL] markers (handled by file delivery pipeline)
text = text.replace(/\[send_file:\s*https?:\/\/[^\]]+\]/g, '').trim();

const MAX = 4000;

function sanitizeTelegramMarkdown(t) {
  const codeBlockCount = (t.match(/```/g) || []).length;
  if (codeBlockCount % 2 !== 0) t += '\n```';
  const boldCount = (t.match(/\*\*/g) || []).length;
  if (boldCount % 2 !== 0) {
    const lastIdx = t.lastIndexOf('**');
    t = t.substring(0, lastIdx) + t.substring(lastIdx + 2);
  }
  let singleStarPositions = [];
  for (let i = 0; i < t.length; i++) {
    if (t[i] === '*' && (i === 0 || t[i-1] !== '*') && (i === t.length-1 || t[i+1] !== '*')) singleStarPositions.push(i);
  }
  if (singleStarPositions.length % 2 !== 0 && singleStarPositions.length > 0) {
    const removeIdx = singleStarPositions[singleStarPositions.length - 1];
    t = t.substring(0, removeIdx) + t.substring(removeIdx + 1);
  }
  let underscorePositions = [];
  for (let i = 0; i < t.length; i++) {
    if (t[i] === '_') {
      const context = t.substring(Math.max(0, i - 50), i);
      if (!context.match(/https?:\/\/[^\s]*$/)) underscorePositions.push(i);
    }
  }
  if (underscorePositions.length % 2 !== 0 && underscorePositions.length > 0) {
    const removeIdx = underscorePositions[underscorePositions.length - 1];
    t = t.substring(0, removeIdx) + t.substring(removeIdx + 1);
  }
  let backtickPositions = [];
  for (let i = 0; i < t.length; i++) {
    if (t[i] === '`' && (i === 0 || t[i-1] !== '`') && (i === t.length-1 || t[i+1] !== '`')) backtickPositions.push(i);
  }
  if (backtickPositions.length % 2 !== 0 && backtickPositions.length > 0) {
    const removeIdx = backtickPositions[backtickPositions.length - 1];
    t = t.substring(0, removeIdx) + t.substring(removeIdx + 1);
  }
  return t;
}

if (text.length <= MAX) {
  return [{ json: { text: sanitizeTelegramMarkdown(text) } }];
}

const chunks = [];
let remaining = text;

while (remaining.length > MAX) {
  let cutPoint = remaining.lastIndexOf('\n\n', MAX);
  if (cutPoint < MAX * 0.3) cutPoint = remaining.lastIndexOf('\n', MAX);
  if (cutPoint < MAX * 0.3) cutPoint = remaining.lastIndexOf(' ', MAX);
  if (cutPoint < MAX * 0.3) cutPoint = MAX;
  chunks.push(remaining.substring(0, cutPoint).trim());
  remaining = remaining.substring(cutPoint).trim();
}
if (remaining) chunks.push(remaining);

return chunks.map(c => ({ json: { text: sanitizeTelegramMarkdown(c) } }));

// Load embedding config from DB and generate embedding
async function getEmbedding(text) {
  const cfgResp = await helpers.httpRequest({ method: 'GET', url: '{{SUPABASE_URL}}/rest/v1/tools_config?tool_name=eq.embedding&select=config,enabled', headers: { 'apikey': '{{SUPABASE_SERVICE_KEY}}', 'Content-Type': 'application/json' } });
  const cfg = (Array.isArray(cfgResp) && cfgResp.length > 0 && cfgResp[0].enabled) ? cfgResp[0].config : null;
  if (!cfg || !cfg.api_key) return null;
  const provider = cfg.provider || 'openai';
  const apiKey = cfg.api_key;
  const model = cfg.model || 'text-embedding-3-small';
  try {
    if (provider === 'openai') {
      const res = await helpers.httpRequest({ method: 'POST', url: 'https://api.openai.com/v1/embeddings', headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ model, input: text }) });
      return res.data[0].embedding;
    }
    if (provider === 'voyage') {
      const res = await helpers.httpRequest({ method: 'POST', url: 'https://api.voyageai.com/v1/embeddings', headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ model: model || 'voyage-3-lite', input: [text] }) });
      return res.data[0].embedding;
    }
    if (provider === 'ollama') {
      const ollamaUrl = cfg.ollama_url || 'http://localhost:11434';
      const res = await helpers.httpRequest({ method: 'POST', url: `${ollamaUrl}/api/embed`, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ model: model || 'nomic-embed-text', input: text }) });
      return res.embeddings[0];
    }
  } catch(e) { return null; }
  return null;
}

let input;
try { input = JSON.parse(query); } catch(e) { input = {search_query: query}; }
const searchQuery = input.search_query || input.query || query;
const filterEntity = input.entity || null;
const filterTags = (input.tags && Array.isArray(input.tags)) ? input.tags.map(t => t.toLowerCase()) : null;
const embedding = await getEmbedding(searchQuery);

const body = { query_text: searchQuery, match_count: 5 };
if (embedding) body.query_embedding = JSON.stringify(embedding);
if (input.category) body.filter_category = input.category;
if (filterEntity) body.filter_entity = filterEntity;
if (filterTags) body.filter_tags = filterTags;
const result = await helpers.httpRequest({
  method: 'POST',
  url: '{{SUPABASE_URL}}/rest/v1/rpc/hybrid_search_memory',
  headers: { 'apikey': '{{SUPABASE_SERVICE_KEY}}', 'Content-Type': 'application/json' },
  body: JSON.stringify(body)
});
return JSON.stringify(result);

