let input;
try { input = JSON.parse(query); } catch(e) { input = {content: query}; }
const content = input.content || query;
const embedding = await getEmbedding(content);
const cat = input.category || 'general';
const imp = input.importance || 5;
const body = { content, category: cat, importance: imp, metadata: { source: 'agent' }, source: input.source || 'conversation' };
if (input.tags && Array.isArray(input.tags)) body.tags = input.tags.map(t => t.toLowerCase());
if (input.entity_name) body.entity_name = input.entity_name;
if (embedding) body.embedding = JSON.stringify(embedding);
// Auto-set expires_at based on category + importance
const neverExpire = ['contact', 'preference', 'decision'];
if (!neverExpire.includes(cat) && imp < 9) {
  const days = (cat === 'consolidated' || imp <= 6) ? 90 : 180;
  body.expires_at = new Date(Date.now() + days * 24 * 60 * 60 * 1000).toISOString();
}
const result = await helpers.httpRequest({
  method: 'POST',
  url: '{{SUPABASE_URL}}/rest/v1/memory_long',
  headers: {
    'apikey': '{{SUPABASE_SERVICE_KEY}}',
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: JSON.stringify(body)
});
return JSON.stringify({ success: true, saved: content, vectorized: !!embedding });

let input;
try { input = JSON.parse(query); } catch(e) { input = {}; }
const id = input.id;
if (!id) return JSON.stringify({ error: 'id is required. Use memory_search first to find the ID.' });
const result = await helpers.httpRequest({
  method: 'DELETE',
  url: `{{SUPABASE_URL}}/rest/v1/memory_long?id=eq.${id}`,
  headers: {
    'apikey': '{{SUPABASE_SERVICE_KEY}}',
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  returnFullResponse: true
});
const body = result.body;
if (Array.isArray(body) && body.length === 0) return JSON.stringify({ error: `Memory with id ${id} not found — it may have already been deleted.` });
return JSON.stringify({ success: true, deleted_id: id });

