let input;
try { input = JSON.parse(query); } catch(e) { input = {}; }
const id = input.id;
if (!id) return JSON.stringify({ error: 'id is required. Use memory_search first to find the ID.' });
const patch = {};
if (input.content) patch.content = input.content;
if (input.category) patch.category = input.category;
if (input.importance) patch.importance = input.importance;
if (input.tags) patch.tags = Array.isArray(input.tags) ? input.tags.map(t => t.toLowerCase()) : input.tags;
if (input.entity_name) patch.entity_name = input.entity_name;
if (input.source) patch.source = input.source;
if (input.metadata && typeof input.metadata === 'object') {
  const existing = await helpers.httpRequest({ method: 'GET', url: `{{SUPABASE_URL}}/rest/v1/memory_long?id=eq.${id}&select=metadata`, headers: { 'apikey': '{{SUPABASE_SERVICE_KEY}}' } });
  const current = (Array.isArray(existing) && existing[0] && existing[0].metadata) ? existing[0].metadata : {};
  patch.metadata = { ...current, ...input.metadata };
}
if (Object.keys(patch).length === 0) return JSON.stringify({ error: 'Provide at least one field to update: content, category, importance, tags, entity_name, source, or metadata.' });
if (input.content) {
  const embedding = await getEmbedding(input.content);
  if (embedding) patch.embedding = JSON.stringify(embedding);
}
patch.updated_at = new Date().toISOString();
const result = await helpers.httpRequest({
  method: 'PATCH',
  url: `{{SUPABASE_URL}}/rest/v1/memory_long?id=eq.${id}`,
  headers: {
    'apikey': '{{SUPABASE_SERVICE_KEY}}',
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: JSON.stringify(patch),
  returnFullResponse: true
});
const body = result.body;
if (Array.isArray(body) && body.length === 0) return JSON.stringify({ error: `Memory with id ${id} not found.` });
return JSON.stringify({ success: true, updated_id: id, fields: Object.keys(patch).filter(k => k !== 'updated_at' && k !== 'embedding'), vectorized: !!patch.embedding });

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';

async function pgrest(method, path, body, extraHeaders = {}) {
  const opts = {
    method,
    url: `${SUPABASE_URL}${path}`,
    headers: { 'apikey': SUPABASE_KEY, 'Content-Type': 'application/json', ...extraHeaders },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  };
  if (body) opts.body = JSON.stringify(body);
  const res = await helpers.httpRequest(opts);
  if (!res.body || res.body === '') return null;
  return typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
}

// Normalize type strings: lowercase, spaces/hyphens to underscores, trim
function normalize(s) {
  if (!s) return null;
  return s.trim().toLowerCase().replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').replace(/[\s-]+/g, '_').replace(/[^a-z0-9_]/g, '');
}

async function getEmbedding(text) {
  const cfgResp = await pgrest('GET', '/rest/v1/tools_config?tool_name=eq.embedding&select=config,enabled');
  const cfg = (Array.isArray(cfgResp) && cfgResp.length > 0 && cfgResp[0].enabled) ? cfgResp[0].config : null;
  if (!cfg || !cfg.api_key) return null;
  const provider = cfg.provider || 'openai';
  const apiKey = cfg.api_key;
  const model = cfg.model || 'text-embedding-3-small';
  try {
    if (provider === 'openai') {
      const res = await helpers.httpRequest({ method: 'POST', url: 'https://api.openai.com/v1/embeddings', headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ model, input: text }) });
      return res.data[0].embedding;
    }
    if (provider === 'voyage') {
      const res = await helpers.httpRequest({ method: 'POST', url: 'https://api.voyageai.com/v1/embeddings', headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ model: model || 'voyage-3-lite', input: [text] }) });
      return res.data[0].embedding;
    }
    if (provider === 'ollama') {
      const ollamaUrl = cfg.ollama_url || 'http://localhost:11434';
      const res = await helpers.httpRequest({ method: 'POST', url: `${ollamaUrl}/api/embed`, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ model: model || 'nomic-embed-text', input: text }) });
      return res.embeddings[0];
    }
  } catch(e) { return null; }
  return null;
}

let input;
try { input = JSON.parse(query); } catch(e) { return 'Error: invalid JSON. Expected: {"action":"search|save|update|relate|graph|delete", ...}'; }
const action = input.action;

if (action === 'search') {
  const body = { match_count: input.limit || 10 };
  if (input.query) {
    const emb = await getEmbedding(input.query);
    if (emb) { body.query_embedding = JSON.stringify(emb); body.match_threshold = 0.5; }
  }
  if (input.name) body.search_name = input.name;
  if (input.type) body.filter_type = normalize(input.type);
  const result = await pgrest('POST', '/rest/v1/rpc/search_entities', body);
  return JSON.stringify(result);

} else if (action === 'save') {
  if (!input.name) return 'Error: name is required';
  // Check if entity already exists (exact name match)
  const existing = await pgrest('GET', `/rest/v1/kg_entities?name=ilike.${encodeURIComponent(input.name)}&select=id,name,entity_type,summary`);
  if (existing && existing.length > 0) return JSON.stringify({ exists: true, entity: existing[0], hint: 'Entity already exists. Use update to modify it.' });
  const entityType = normalize(input.entity_type);
  const body = { name: input.name, entity_type: entityType, summary: input.summary || null, metadata: input.metadata || {} };
  const embText = input.name + (input.summary ? ' ' + input.summary : '');
  const emb = await getEmbedding(embText);
  if (emb) body.embedding = JSON.stringify(emb);
  const result = await pgrest('POST', '/rest/v1/kg_entities', body, { 'Prefer': 'return=representation' });
  // Return existing types so agent stays consistent
  const types = await pgrest('GET', '/rest/v1/kg_entities?select=entity_type&entity_type=not.is.null&order=entity_type');
  const usedTypes = [...new Set((types || []).map(t => t.entity_type).filter(Boolean))];
  // Find existing memories about this entity
  const relatedMemories = await pgrest('GET', `/rest/v1/memory_long?entity_name=ilike.${encodeURIComponent(input.name)}&select=id,content,category,tags&order=importance.desc&limit=5`);
  const response = { success: true, entity: Array.isArray(result) ? result[0] : result, existing_entity_types: usedTypes };
  if (relatedMemories && relatedMemories.length > 0) response.related_memories = relatedMemories;
  return JSON.stringify(response);

} else if (action === 'update') {
  if (!input.id) return 'Error: id (UUID) is required';
  const patch = {};
  if (input.name) patch.name = input.name;
  if (input.entity_type) patch.entity_type = normalize(input.entity_type);
  if (input.summary !== undefined) patch.summary = input.summary;
  if (input.metadata) patch.metadata = input.metadata;
  if (Object.keys(patch).length === 0) return 'Error: provide at least one field to update';
  if (input.name || input.summary) {
    const current = await pgrest('GET', `/rest/v1/kg_entities?id=eq.${input.id}&select=name,summary`);
    const e = Array.isArray(current) && current[0] ? current[0] : {};
    const embText = (patch.name || e.name) + ' ' + (patch.summary || e.summary || '');
    const emb = await getEmbedding(embText);
    if (emb) patch.embedding = JSON.stringify(emb);
  }
  patch.updated_at = new Date().toISOString();
  const result = await pgrest('PATCH', `/rest/v1/kg_entities?id=eq.${input.id}`, patch, { 'Prefer': 'return=representation' });
  if (Array.isArray(result) && result.length === 0) return JSON.stringify({ error: `Entity ${input.id} not found` });
  return JSON.stringify({ success: true, entity: Array.isArray(result) ? result[0] : result });

} else if (action === 'relate') {
  if (!input.source_name || !input.target_name || !input.relation_type) return 'Error: source_name, target_name, and relation_type are required';
  const relType = normalize(input.relation_type);
  // Resolve names to IDs
  const srcList = await pgrest('GET', `/rest/v1/kg_entities?name=ilike.${encodeURIComponent(input.source_name)}&select=id,name`);
  const tgtList = await pgrest('GET', `/rest/v1/kg_entities?name=ilike.${encodeURIComponent(input.target_name)}&select=id,name`);
  if (!srcList || srcList.length === 0) return `Error: entity "${input.source_name}" not found. Save it first with action "save".`;
  if (!tgtList || tgtList.length === 0) return `Error: entity "${input.target_name}" not found. Save it first with action "save".`;
  // Check for duplicate relation
  const dupCheck = await pgrest('GET', `/rest/v1/kg_relations?source_id=eq.${srcList[0].id}&target_id=eq.${tgtList[0].id}&relation_type=eq.${encodeURIComponent(relType)}&valid_until=is.null&select=id`);
  if (dupCheck && dupCheck.length > 0) return JSON.stringify({ exists: true, relation_id: dupCheck[0].id, hint: 'This relation already exists.' });
  const body = {
    source_id: srcList[0].id,
    target_id: tgtList[0].id,
    relation_type: relType,
    weight: input.weight || 1.0,
    metadata: input.metadata || {}
  };
  if (input.valid_from) body.valid_from = input.valid_from;
  if (input.valid_until) body.valid_until = input.valid_until;
  const result = await pgrest('POST', '/rest/v1/kg_relations', body, { 'Prefer': 'return=representation' });
  // Return existing relation types so agent stays consistent
  const rtypes = await pgrest('GET', '/rest/v1/kg_relations?select=relation_type&order=relation_type');
  const usedRelTypes = [...new Set((rtypes || []).map(r => r.relation_type).filter(Boolean))];
  return JSON.stringify({ success: true, relation: Array.isArray(result) ? result[0] : result, existing_relation_types: usedRelTypes });

} else if (action === 'graph') {
  if (!input.name) return 'Error: name is required';
  const entities = await pgrest('GET', `/rest/v1/kg_entities?name=ilike.${encodeURIComponent(input.name)}&select=id,name,entity_type,summary`);
  if (!entities || entities.length === 0) return `Error: entity "${input.name}" not found`;
  const startEntity = entities[0];
  const graph = await pgrest('POST', '/rest/v1/rpc/search_entity_graph', { start_id: startEntity.id, max_depth: input.depth || 2 });
  // Include related memories for the center entity
  const memories = await pgrest('GET', `/rest/v1/memory_long?entity_name=ilike.${encodeURIComponent(input.name)}&select=id,content,category,tags&order=importance.desc&limit=5`);
  const response = { center: startEntity, connections: graph };
  if (memories && memories.length > 0) response.related_memories = memories;
  return JSON.stringify(response);

} else if (action === 'delete') {
  if (!input.id) return 'Error: id (UUID) is required';
  await pgrest('DELETE', `/rest/v1/kg_entities?id=eq.${input.id}`);
  return JSON.stringify({ success: true, deleted_id: input.id });

} else {
  return 'Error: unknown action "' + action + '". Use: search, save, update, relate, graph, delete';
}

let input;
try { input = JSON.parse(query); } catch(e) { input = {url: query}; }
if (!input.url) return 'Fehler: url ist Pflicht';
const result = await helpers.httpRequest({
  method: input.method || 'GET',
  url: input.url,
  headers: input.headers || {}
});
return typeof result === 'string' ? result.substring(0,4000) : JSON.stringify(result).substring(0,4000);

let input;
try { input = JSON.parse(query); } catch(e) { input = { q: query }; }
const q = input.q || input.query || query;
const result = await helpers.httpRequest({
  method: 'GET',
  url: `http://searxng:8080/search?q=${encodeURIComponent(q)}&format=json&language=de`,
  headers: { 'Accept': 'application/json' }
});
const hits = (result.results || []).slice(0, 5).map(r =>
  `${r.title}\n${r.url}\n${r.content || ''}`
).join('\n\n');
return hits || 'Keine Ergebnisse gefunden.';

let input;
try { input = JSON.parse(query); } catch(e) { input = { url: query }; }
if (!input.url) return 'Fehler: url ist Pflicht';
try {
  const resp = await helpers.httpRequest({
    method: 'POST',
    url: 'http://crawl4ai:11235/crawl',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ urls: [input.url], crawler_config: { type: 'CrawlerRunConfig', params: { stream: false, cache_mode: 'bypass' } } }),
    timeout: 30000
  });
  const results = resp.results || resp;
  const result = Array.isArray(results) ? results[0] : results;
  if (!result.success) return 'Fehler: ' + (result.error_message || 'Crawl fehlgeschlagen');
  const mdObj = result.markdown || {};
  const md = typeof mdObj === 'string' ? mdObj : (mdObj.raw_markdown || '');
  return md.substring(0, 8000);
} catch(e) {
  return 'Fehler beim Abrufen: ' + e.message;
}

let input;
try { input = JSON.parse(query); } catch(e) { input = {action:'list'}; }
const apiKey = '{{N8N_API_KEY}}';
const hdrs = {'X-N8N-API-KEY': apiKey, 'Content-Type': 'application/json'};
let result;
if (input.action === 'list') {
  result = await helpers.httpRequest({method:'GET', url:'{{N8N_INTERNAL_URL}}/api/v1/workflows', headers: hdrs});
} else if (input.action === 'get' && input.workflowId) {
  result = await helpers.httpRequest({method:'GET', url:'{{N8N_INTERNAL_URL}}/api/v1/workflows/'+input.workflowId, headers: hdrs});
} else {
  return JSON.stringify({error: 'Use action: list or get'});
}
return JSON.stringify(result);

const qType = typeof query;
let mcpUrl = '', toolName = '', args = {};

if (qType === 'object' && query !== null) {
  mcpUrl = query.mcp_url || '';
  toolName = query.tool_name || '';
  args = query.arguments || {};
} else if (qType === 'string') {
  try {
    const parsed = JSON.parse(query);
    mcpUrl = parsed.mcp_url || '';
    toolName = parsed.tool_name || '';
    args = parsed.arguments || {};
  } catch(e) {
    return 'Parse error: query=' + String(query).substring(0,200) + ' type=' + qType;
  }
} else {
  return 'Unexpected query type: ' + qType + ' value: ' + String(query).substring(0,200);
}

if (typeof args === 'string') try { args = JSON.parse(args); } catch(e) {}
if (!mcpUrl || !toolName) return 'Fehler: mcp_url=' + mcpUrl + ' tool_name=' + toolName + ' (query type was: ' + qType + ')';

function parseSSE(raw) {
  const str = String(raw);
  let lines = str.split('\n');
  if (lines.length <= 1) lines = str.split('\\n');
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (line.startsWith('data: ')) {
      return JSON.parse(line.substring(6));
    }
  }
  return null;
}

try {
  let authHeader = null;
  try {
    const row = await helpers.httpRequest({method:'GET',url:'{{SUPABASE_URL}}/rest/v1/mcp_registry?mcp_url=eq.'+encodeURIComponent(mcpUrl)+'&select=auth_type,auth_token&limit=1',headers:{apikey:'{{SUPABASE_SERVICE_KEY}}',Authorization:'Bearer {{SUPABASE_SERVICE_KEY}}'},json:true});
    if (row && row[0] && row[0].auth_type && row[0].auth_type !== 'none' && row[0].auth_token) {
      authHeader = row[0].auth_type === 'bearer' ? 'Bearer '+row[0].auth_token : row[0].auth_token;
    }
  } catch(e) {}

  const hdrs = {'Content-Type':'application/json','Accept':'application/json, text/event-stream'};
  if (authHeader) hdrs['Authorization'] = authHeader;

  // 1. Initialize
  const init = await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',id:1,method:'initialize',params:{protocolVersion:'2024-11-05',capabilities:{},clientInfo:{name:'n8n-claw-mcp',version:'1.0'}}}),
    returnFullResponse: true, encoding: 'utf-8', json: false
  });
  const sid = init.headers && init.headers['mcp-session-id'];
  if (sid) hdrs['mcp-session-id'] = sid;

  // 2. Initialized notification
  await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',method:'notifications/initialized'}),
    json: false
  });

  // 3. List tools to get schemas (auto-fill missing required params)
  const listResp = await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',id:2,method:'tools/list',params:{}}),
    json: false
  });
  const listResult = parseSSE(listResp);
  let toolSchema = null;
  if (listResult && listResult.result && listResult.result.tools) {
    const tool = listResult.result.tools.find(t => t.name === toolName);
    if (tool && tool.inputSchema) toolSchema = tool.inputSchema;
  }

  function schemaHint(problem) {
    if (!toolSchema) return null;
    return 'Tool "' + toolName + '" call rejected: ' + problem +
      '\n\nCorrect input schema:\n' + JSON.stringify(toolSchema, null, 2) +
      '\n\nRetry the tool call with parameter names matching this schema exactly.';
  }

  if (toolSchema && toolSchema.properties) {
    const allowed = Object.keys(toolSchema.properties);
    const required = toolSchema.required || [];
    const unknown = Object.keys(args).filter(k => !allowed.includes(k));
    const missing = required.filter(r => args[r] === undefined || args[r] === null);
    if (unknown.length > 0 || missing.length > 0) {
      const problems = [];
      if (unknown.length > 0) problems.push('unknown args [' + unknown.join(', ') + ']');
      if (missing.length > 0) problems.push('missing required args [' + missing.join(', ') + ']');
      return schemaHint(problems.join('; '));
    }
  }

  const resp = await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',id:3,method:'tools/call',params:{name:toolName,arguments:args}}),
    returnFullResponse: true, encoding: 'utf-8', json: false
  });

  const result = parseSSE(resp.body || resp);
  if (!result) return String(resp.body || resp);
  if (result.error) {
    return schemaHint('server error: ' + JSON.stringify(result.error)) || ('MCP Error: ' + JSON.stringify(result.error));
  }
  if (result.result && result.result.isError) {
    const errText = (result.result.content && result.result.content[0] && result.result.content[0].text) || JSON.stringify(result.result);
    return schemaHint('tool returned error: ' + errText) || ('MCP Tool Error: ' + errText);
  }
  return result.result?.content?.[0]?.text || JSON.stringify(result.result);
} catch(e) {
  return 'MCP Error: ' + e.message;
}

parameters.description:
Manage tasks. Input: JSON with action and parameters.

Actions:
- list: List tasks. Optional: status (pending/in_progress/done/cancelled), priority, due_before (ISO date)
- create: Create task. Required: title. Optional: description, priority (low/medium/high/urgent), due_date (ISO 8601), parent_id (for subtasks), tags (array)
- update: Update task. Required: id. Optional: title, description, status, priority, due_date, tags
- delete: Delete task. Required: id
- summary: Overview of all pending/in_progress tasks grouped by priority
- set_preference: Save user preference. Required: key, value. Example: {"action":"set_preference","key":"morning_briefing","value":{"enabled":true,"time":"08:00"}}

Examples:
{"action":"create","title":"Call dentist","due_date":"2026-03-10T10:00:00+01:00","priority":"high"}
{"action":"list","status":"pending"}
{"action":"update","id":5,"status":"done"}
{"action":"summary"}

parameters.jsCode:
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const CHAT_ID = '{{TELEGRAM_CHAT_ID}}';

async function pgrest(method, path, body, extraHeaders = {}) {
  const opts = {
    method,
    url: `${SUPABASE_URL}${path}`,
    headers: { 'apikey': SUPABASE_KEY, 'Content-Type': 'application/json', ...extraHeaders },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  };
  if (body) opts.body = JSON.stringify(body);
  const res = await helpers.httpRequest(opts);
  if (!res.body || res.body === '') return null;
  return typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
}

let input;
try { input = JSON.parse(query); } catch(e) { return 'Error: invalid JSON. Expected: {"action":"list|create|update|delete|summary|set_preference", ...}'; }

const userId = `telegram:${CHAT_ID}`;
const action = input.action;

if (action === 'list') {
  let filter = `user_id=eq.${encodeURIComponent(userId)}`;
  if (input.status) filter += `&status=eq.${input.status}`;
  if (input.priority) filter += `&priority=eq.${input.priority}`;
  if (input.due_before) filter += `&due_date=lte.${input.due_before}`;
  filter += '&parent_id=is.null&order=due_date.asc.nullslast,priority.desc,created_at.desc';
  const tasks = await pgrest('GET', `/rest/v1/tasks?${filter}&select=*`);
  return JSON.stringify(tasks);

} else if (action === 'create') {
  if (!input.title) return 'Error: title is required';
  const body = {
    user_id: userId,
    title: input.title,
    description: input.description || null,
    priority: input.priority || 'medium',
    due_date: input.due_date || null,
    parent_id: input.parent_id || null,
    tags: input.tags || []
  };
  const result = await pgrest('POST', '/rest/v1/tasks', body, { 'Prefer': 'return=representation' });
  return JSON.stringify({ success: true, task: Array.isArray(result) ? result[0] : result });

} else if (action === 'update') {
  if (!input.id) return 'Error: id is required';
  const body = {};
  if (input.title) body.title = input.title;
  if (input.description !== undefined) body.description = input.description;
  if (input.status) {
    body.status = input.status;
    if (input.status === 'done') body.completed_at = new Date().toISOString();
  }
  if (input.priority) body.priority = input.priority;
  if (input.due_date !== undefined) body.due_date = input.due_date;
  if (input.tags) body.tags = input.tags;
  body.updated_at = new Date().toISOString();
  const result = await pgrest('PATCH', `/rest/v1/tasks?id=eq.${input.id}&user_id=eq.${encodeURIComponent(userId)}`, body, { 'Prefer': 'return=representation' });
  return JSON.stringify({ success: true, task: Array.isArray(result) ? result[0] : result });

} else if (action === 'delete') {
  if (!input.id) return 'Error: id is required';
  await pgrest('DELETE', `/rest/v1/tasks?id=eq.${input.id}&user_id=eq.${encodeURIComponent(userId)}`);
  return JSON.stringify({ success: true, deleted: input.id });

} else if (action === 'summary') {
  const tasks = await pgrest('GET', `/rest/v1/tasks?user_id=eq.${encodeURIComponent(userId)}&status=in.(pending,in_progress)&parent_id=is.null&order=priority.desc,due_date.asc.nullslast&select=*`);
  const profiles = await pgrest('GET', `/rest/v1/user_profiles?user_id=eq.${encodeURIComponent(userId)}&select=timezone`);
  const tz = (profiles && profiles[0] && profiles[0].timezone) || 'Europe/Berlin';
  const now = new Date();
  const todayStr = now.toLocaleDateString('en-CA', { timeZone: tz });
  const overdue = tasks.filter(t => { if (!t.due_date) return false; const d = new Date(t.due_date); return d < now && d.toLocaleDateString('en-CA', { timeZone: tz }) !== todayStr; });
  const dueToday = tasks.filter(t => { if (!t.due_date) return false; return new Date(t.due_date).toLocaleDateString('en-CA', { timeZone: tz }) === todayStr; });
  return JSON.stringify({
    total_pending: tasks.length, overdue: overdue.length, due_today: dueToday.length,
    by_priority: { urgent: tasks.filter(t => t.priority === 'urgent').length, high: tasks.filter(t => t.priority === 'high').length, medium: tasks.filter(t => t.priority === 'medium').length, low: tasks.filter(t => t.priority === 'low').length },
    tasks: tasks.map(t => ({ id: t.id, title: t.title, status: t.status, priority: t.priority, due_date: t.due_date }))
  });

} else if (action === 'set_preference') {
  if (!input.key || input.value === undefined) return 'Error: key and value required';
  const profiles = await pgrest('GET', `/rest/v1/user_profiles?user_id=eq.${encodeURIComponent(userId)}&select=preferences`);
  const current = (profiles[0] && profiles[0].preferences) || {};
  current[input.key] = input.value;
  await pgrest('PATCH', `/rest/v1/user_profiles?user_id=eq.${encodeURIComponent(userId)}`, { preferences: current, updated_at: new Date().toISOString() }, { 'Prefer': 'return=minimal' });
  if (input.key === 'morning_briefing' && input.value.enabled !== undefined) {
    await pgrest('PATCH', `/rest/v1/heartbeat_config?check_name=eq.morning_briefing`, { enabled: input.value.enabled }, { 'Prefer': 'return=minimal' });
  }
  return JSON.stringify({ success: true, preference: input.key, value: input.value });

} else {
  return 'Error: unknown action "' + action + '". Use: list, create, update, delete, summary, set_preference';
}

parameters.description:
Manage the MCP template library. Install, list, or remove MCP server templates from the catalog. Add API credentials for installed templates.

Actions:
- list_templates: Show available templates. Optional: category filter.
- install_template: Install a template by ID. Creates the MCP server workflow.
- remove_template: Remove an installed template by ID.
- add_credential: Generate secure one-time link(s) to add/update API key(s) for an installed template. Required: id. Optional: cred_key (if omitted, generates links for ALL required credentials).

Input: JSON with action and parameters.
Examples:
{"action":"list_templates"}
{"action":"install_template","id":"weather-openmeteo"}
{"action":"remove_template","id":"weather-openmeteo"}
{"action":"add_credential","id":"google-reviews"}

Manage projects — persistent markdown documents for tracking ongoing work across conversations. Use this when a topic spans multiple sessions (e.g. building a presentation, planning an event, setting up a server).

Input: JSON with action and fields:
- list: Returns all projects with name, status, updated_at.
- read: name (string). Returns the full markdown content.
- create: name (string), content (string, markdown). Creates a new project.
- update: name (string), content (string, markdown). Replaces the entire project content. Always read first, then send the complete updated document.
- archive: name (string). Sets status to completed.

Examples:
{"action":"list"}
{"action":"create","name":"KI Präsentation","content":"## Ziel\nPräsentation über KI im Tourismus\n\n## Gliederung\n1. Einführung\n2. Use Cases"}
{"action":"read","name":"KI Präsentation"}
{"action":"update","name":"KI Präsentation","content":"## Ziel\n...updated content..."}
{"action":"archive","name":"KI Präsentation"}

parameters.jsCode:
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';

async function pgrest(method, path, body, extraHeaders = {}) {
  const opts = {
    method,
    url: `${SUPABASE_URL}${path}`,
    headers: { 'apikey': SUPABASE_KEY, 'Content-Type': 'application/json', ...extraHeaders },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  };
  if (body) opts.body = JSON.stringify(body);
  const res = await helpers.httpRequest(opts);
  if (!res.body || res.body === '') return null;
  return typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
}

let input;
try { input = JSON.parse(query); } catch(e) { return 'Error: invalid JSON. Expected: {"action":"list|read|create|update|archive", ...}'; }

const action = input.action;

if (action === 'list') {
  const projects = await pgrest('GET', '/rest/v1/projects?order=updated_at.desc&select=name,status,updated_at');
  if (!projects || projects.length === 0) return JSON.stringify({ projects: [], message: 'No projects yet.' });
  return JSON.stringify({ projects });

} else if (action === 'read') {
  if (!input.name) return 'Error: name is required';
  const projects = await pgrest('GET', `/rest/v1/projects?name=eq.${encodeURIComponent(input.name)}&select=name,status,content,created_at,updated_at`);
  if (!projects || projects.length === 0) return JSON.stringify({ error: 'Project not found: ' + input.name });
  return JSON.stringify(projects[0]);

} else if (action === 'create') {
  if (!input.name) return 'Error: name is required';
  const body = { name: input.name, content: input.content || '', status: 'active' };
  const result = await pgrest('POST', '/rest/v1/projects', body, { 'Prefer': 'return=representation' });
  if (result && result.code) return JSON.stringify({ error: result.message || 'Create failed' });
  return JSON.stringify({ success: true, project: Array.isArray(result) ? result[0] : result });

} else if (action === 'update') {
  if (!input.name) return 'Error: name is required';
  if (input.content === undefined) return 'Error: content is required';
  const body = { content: input.content, updated_at: new Date().toISOString() };
  if (input.status) body.status = input.status;
  const result = await pgrest('PATCH', `/rest/v1/projects?name=eq.${encodeURIComponent(input.name)}`, body, { 'Prefer': 'return=representation' });
  if (!result || result.length === 0) return JSON.stringify({ error: 'Project not found: ' + input.name });
  return JSON.stringify({ success: true, project: Array.isArray(result) ? result[0] : result });

} else if (action === 'archive') {
  if (!input.name) return 'Error: name is required';
  const body = { status: 'completed', updated_at: new Date().toISOString() };
  const result = await pgrest('PATCH', `/rest/v1/projects?name=eq.${encodeURIComponent(input.name)}`, body, { 'Prefer': 'return=representation' });
  if (!result || result.length === 0) return JSON.stringify({ error: 'Project not found: ' + input.name });
  return JSON.stringify({ success: true, archived: input.name });

} else {
  return 'Error: unknown action "' + action + '". Use: list, read, create, update, archive';
}

parameters.description:
Delegate a task to a specialized expert agent. The expert works independently with its own AI model and tools, then returns a structured result. You should rephrase the result in your own tone before replying to the user.

Parameters (JSON):
- agent: Expert agent identifier (e.g. "research-expert", "content-creator", "data-analyst")
- task: Detailed task description — be specific about what you need
- context: Relevant conversation context the expert should know (optional)

Examples:
{"agent":"research-expert","task":"Recherchiere die besten Wanderwege in Tirol mit Schwierigkeitsgrad und Länge","context":"User plant einen Wanderurlaub im Sommer"}
{"agent":"content-creator","task":"Erstelle einen Instagram-Post über unser neues Produkt","context":"Produkt: AI-gestützter Kalender, Zielgruppe: junge Berufstätige"}
{"agent":"data-analyst","task":"Analysiere diese Verkaufszahlen und erstelle einen Report","context":"Q1 2026: Jan 45k, Feb 52k, Mär 61k"}

Manage the expert agent library. Install, list, or remove specialized expert agents from the catalog.

Actions:
- list_agents: Show all available agents from the catalog (with installed status).
- install_agent: Install an agent by ID. Downloads persona from catalog and saves to database.
- remove_agent: Remove an installed agent by ID.
- list_installed: Show only currently installed agents.

Input: JSON with action and parameters.
Examples:
{"action":"list_agents"}
{"action":"install_agent","id":"research-expert"}
{"action":"remove_agent","id":"research-expert"}
{"action":"list_installed"}

