const body = $('Webhook Trigger').first().json.body;
const message = body.message || '';
const rawUserId = body.user_id || 'anonymous';
const rawSessionId = body.session_id || '';
const source = body.source || 'api';
const metadata = body.metadata || {};

// Build qualified IDs with source prefix
const qualifiedUserId = rawUserId.includes(':') ? rawUserId : `api:${rawUserId}`;
const sessionId = rawSessionId
  ? (rawSessionId.includes(':') ? rawSessionId : `${source}:${rawSessionId}`)
  : `${source}:${rawUserId}`;

return [{ json: {
  userMessage: message,
  chatId: null,
  userId: rawUserId,
  sessionId,
  qualifiedUserId,
  source,
  metadata,
  _webhookSource: true
} }];

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const BRIDGE_URL = 'http://file-bridge:3200';

const msg = $('Telegram Trigger').first().json.message;
const sessionId = 'telegram:' + String(msg.chat.id);
const userId = String(msg.from.id);
const upload = $input.first().json;

if (!upload || !upload.id) {
  return [{ json: { file_ref: null } }];
}

await helpers.httpRequest({
  method: 'POST',
  url: SUPABASE_URL + '/rest/v1/file_refs',
  headers: {
    'apikey': SUPABASE_KEY,
    'Authorization': 'Bearer ' + SUPABASE_KEY,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    id: upload.id,
    session_id: sessionId,
    user_id: userId,
    file_name: upload.file_name,
    mime_type: upload.mime_type,
    size_bytes: upload.size_bytes,
    bridge_url: BRIDGE_URL + '/files/' + upload.id
  })
});

return [{ json: { file_ref: upload.id, file_name: upload.file_name } }];

const output = $('AI Agent').first().json.output || '';

// Detect [send_file: URL] pattern
const fileMatch = output.match(/\[send_file:\s*(https?:\/\/[^\]]+)\]/);

let cleanText = output;
let fileUrl = null;
let hasFile = false;

if (fileMatch) {
  fileUrl = fileMatch[1].trim();
  hasFile = true;
  // Remove the marker from the text response
  cleanText = output.replace(fileMatch[0], '').trim();
}

return [{ json: { text: cleanText, fileUrl, hasFile } }];

// Load due scheduled actions + proactive reminder check + open loop check
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const CHAT_ID = '{{TELEGRAM_CHAT_ID}}';
const http = this.helpers.httpRequest;

async function pgrest(path) {
  const res = await http({
    method: 'GET',
    url: `${SUPABASE_URL}${path}`,
    headers: { 'apikey': SUPABASE_KEY, 'Content-Type': 'application/json' },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  return typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
}

const userId = `telegram:${CHAT_ID}`;
const now = new Date();
const nowISO = now.toISOString();

// Load all context in parallel
const [dueActions, tasks, profiles, heartbeatCfg, mcpServers, openLoopCfg] = await Promise.all([
  pgrest(`/rest/v1/scheduled_actions?enabled=eq.true&next_run=lte.${nowISO}&order=next_run.asc`),
  pgrest(`/rest/v1/tasks?user_id=eq.${encodeURIComponent(userId)}&status=in.(pending,in_progress)&order=due_date.asc.nullslast,priority.desc`),
  pgrest(`/rest/v1/user_profiles?user_id=eq.${encodeURIComponent(userId)}&select=display_name,timezone,preferences`),
  pgrest('/rest/v1/heartbeat_config?check_name=eq.heartbeat&select=config,last_run,enabled'),
  pgrest('/rest/v1/mcp_registry?active=eq.true&select=server_name,mcp_url,description,tools'),
  pgrest('/rest/v1/heartbeat_config?check_name=eq.open_loop_check&select=config,last_run,enabled')
]);

const profile = (Array.isArray(profiles) && profiles.length > 0) ? profiles[0] : {};
const prefs = profile.preferences || {};
const tz = profile.timezone || 'Europe/Berlin';
const lang = prefs.language || 'German';

// Build MCP skills text for background checker
let mcpSkillsText = '';
if (Array.isArray(mcpServers) && mcpServers.length > 0) {
  mcpSkillsText = mcpServers.map(s => {
    const tools = Array.isArray(s.tools) ? s.tools.join(', ') : '';
    return `- ${s.server_name}: ${s.mcp_url} (tools: ${tools}) — ${s.description || ''}`;
  }).join('\n');
}

// Build result items from due scheduled actions
const items = [];

if (Array.isArray(dueActions)) {
  for (const action of dueActions) {
    items.push({
      json: {
        type: 'scheduled_action',
        actionId: action.id,
        message: action.instruction,
        chat_id: action.chat_id,
        user_id: action.user_id,
        source: 'scheduled_action',
        schedule: action.schedule,
        timezone: action.timezone || tz,
        run_count: action.run_count || 0,
        max_runs: action.max_runs,
        name: action.name,
        notify_mode: action.notify_mode || 'always',
        last_run: action.last_run || null,
        mcp_skills: mcpSkillsText,
        language: lang
      }
    });
  }
}

// Proactive reminder check (existing logic — kept as synthetic item)
const hbEnabled = (Array.isArray(heartbeatCfg) && heartbeatCfg.length > 0) ? heartbeatCfg[0].enabled : false;
const hbLastRun = (Array.isArray(heartbeatCfg) && heartbeatCfg.length > 0 && heartbeatCfg[0].last_run) ? new Date(heartbeatCfg[0].last_run) : null;
const hbMinInterval = (Array.isArray(heartbeatCfg) && heartbeatCfg.length > 0 && heartbeatCfg[0].config) ? (heartbeatCfg[0].config.min_interval_hours || 2) : 2;

if (hbEnabled) {
  const hoursSinceLastRun = hbLastRun ? (now.getTime() - hbLastRun.getTime()) / (1000 * 60 * 60) : 999;
  if (hoursSinceLastRun >= hbMinInterval) {
    const taskList = Array.isArray(tasks) ? tasks : [];
    const overdue = taskList.filter(t => t.due_date && new Date(t.due_date) < now);
    const urgentCutoff = new Date(now.getTime() + 24 * 60 * 60 * 1000);
    const urgent = taskList.filter(t => t.priority === 'urgent' && (!t.due_date || new Date(t.due_date) <= urgentCutoff));

    if (overdue.length > 0 || urgent.length > 0) {
      let instruction = `You are proactively checking in with the user. Respond in ${lang}. Send a brief, helpful reminder (1-3 sentences) about these items:\n`;
      if (overdue.length > 0) {
        instruction += `\nOverdue tasks:\n${overdue.map(t => `- ${t.title} (due: ${t.due_date}, priority: ${t.priority})`).join('\n')}`;
      }
      if (urgent.length > 0) {
        instruction += `\nUrgent tasks:\n${urgent.map(t => `- ${t.title}`).join('\n')}`;
      }
      instruction += `\n\nBe helpful, not annoying. If nothing seems worth messaging about, just skip this.`;

      items.push({
        json: {
          type: 'proactive_reminder',
          heartbeat_check_name: 'heartbeat',
          actionId: null,
          message: instruction,
          chat_id: CHAT_ID,
          user_id: userId,
          source: 'scheduled_action',
          notify_mode: 'always'
        }
      });
    }
  }
}

// NEW: Open Loop check (every ~24h, configurable). Asks the user about old unfinished intentions.
const olCfg = (Array.isArray(openLoopCfg) && openLoopCfg.length > 0) ? openLoopCfg[0] : null;
const olEnabled = olCfg ? olCfg.enabled : false;
const olLastRun = (olCfg && olCfg.last_run) ? new Date(olCfg.last_run) : null;
const olMinInterval = (olCfg && olCfg.config) ? (olCfg.config.min_interval_hours || 24) : 24;
const olMinAgeDays = (olCfg && olCfg.config) ? (olCfg.config.min_age_days || 3) : 3;

if (olEnabled) {
  const hoursSinceOL = olLastRun ? (now.getTime() - olLastRun.getTime()) / (1000 * 60 * 60) : 999;
  if (hoursSinceOL >= olMinInterval) {
    const ageCutoff = new Date(now.getTime() - olMinAgeDays * 24 * 60 * 60 * 1000).toISOString();
    const openLoops = await pgrest(`/rest/v1/memory_long?category=eq.open_loop&created_at=lt.${ageCutoff}&or=(expires_at.is.null,expires_at.gt.${nowISO})&select=id,content,importance,created_at,expires_at,metadata&order=importance.desc,created_at.asc&limit=10`);
    // Filter out closed entries client-side (PostgREST jsonb-path filtering is awkward across versions)
    const active = (Array.isArray(openLoops) ? openLoops : []).filter(ol => {
      const m = ol.metadata || {};
      return m.closed !== true && m.closed !== 'true';
    }).slice(0, 3);

    if (active.length > 0) {
      const lines = active.map(ol => {
        const days = Math.max(1, Math.floor((now.getTime() - new Date(ol.created_at).getTime()) / (1000 * 60 * 60 * 24)));
        return `- (id ${ol.id}, vor ${days} Tagen) ${ol.content}`;
      }).join('\n');

      const instruction = `Du fragst proaktiv beim User nach alten offenen Vorhaben. Antworte auf ${lang}. Sende EINE kurze, freundliche Nachricht (1-3 Sätze), die EINEN oder mehrere der folgenden offenen Punkte aufgreift. Sei nicht nervig — wenn ein Punkt zu trivial wirkt, lass ihn aus. Wenn alle Punkte trivial wirken, antworte nur mit dem Text [SKIP] und nichts anderem.\n\nWenn der User in seiner Antwort bestätigt, dass etwas erledigt/verworfen wurde, nutze memory_update auf die jeweilige id und setze metadata.closed=true (siehe Memory-Behavior-Regeln zu open_loop).\n\nOffene Vorhaben:\n${lines}`;

      items.push({
        json: {
          type: 'proactive_reminder',
          heartbeat_check_name: 'open_loop_check',
          actionId: null,
          message: instruction,
          chat_id: CHAT_ID,
          user_id: userId,
          source: 'scheduled_action',
          notify_mode: 'always'
        }
      });
    }
  }
}

if (items.length === 0) {
  return [{ json: { type: 'no_action' } }];
}

return items;

// Merge checker result with original action data for routing + update
const checkerResult = $input.first().json;
const actionData = $('Route by Notify Mode').first().json;

return [{
  json: {
    ...actionData,
    notify: checkerResult.notify || false,
    checkerMessage: checkerResult.message || ''
  }
}];

// Update scheduled action: last_run, run_count, next_run
const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const http = this.helpers.httpRequest;

// Get the action data — always original data from Should Notify
// (Send Telegram is a dead-end, doesn't feed into Update Action)
const item = $input.first().json;
const now = new Date();

// Proactive reminder: update heartbeat_config (configurable check_name to support multiple proactive triggers)
if (item.type === 'proactive_reminder') {
  const checkName = item.heartbeat_check_name || 'heartbeat';
  await http({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/heartbeat_config?check_name=eq.${checkName}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: { last_run: now.toISOString() }
  });
  return [{ json: { status: 'updated', type: 'proactive_reminder', check: checkName } }];
}

// Scheduled action: compute next_run and update
const actionId = item.actionId;
const schedule = item.schedule;
const tz = item.timezone || 'Europe/Berlin';
const runCount = (item.run_count || 0) + 1;
const maxRuns = item.max_runs;

function computeNextRun(schedule, tz) {
  const now = new Date();

  if (schedule.type === 'interval') {
    // Subtract 30s buffer so the next heartbeat cycle reliably finds this action due
    return new Date(now.getTime() + (schedule.minutes || 60) * 60000 - 30000).toISOString();
  }

  if (schedule.type === 'daily') {
    const [h, m] = (schedule.time || '08:00').split(':').map(Number);
    const userNow = new Date(now.toLocaleString('en-US', { timeZone: tz }));
    const target = new Date(userNow);
    target.setHours(h, m, 0, 0);
    if (target <= userNow) {
      target.setDate(target.getDate() + 1);
    }
    const diffMs = target.getTime() - userNow.getTime();
    return new Date(now.getTime() + diffMs).toISOString();
  }

  if (schedule.type === 'weekly') {
    const [h, m] = (schedule.time || '09:00').split(':').map(Number);
    const days = schedule.days || [1];
    const userNow = new Date(now.toLocaleString('en-US', { timeZone: tz }));
    const jsDay = userNow.getDay();
    const currentDay = jsDay === 0 ? 7 : jsDay;
    const currentMinutes = userNow.getHours() * 60 + userNow.getMinutes();
    const targetMinutes = h * 60 + m;

    let minDaysAhead = 8;
    for (const d of days) {
      let ahead = d - currentDay;
      if (ahead < 0) ahead += 7;
      if (ahead === 0 && currentMinutes >= targetMinutes) ahead = 7;
      if (ahead < minDaysAhead) minDaysAhead = ahead;
    }

    const target = new Date(userNow);
    target.setDate(target.getDate() + minDaysAhead);
    target.setHours(h, m, 0, 0);
    const diffMs = target.getTime() - userNow.getTime();
    return new Date(now.getTime() + diffMs).toISOString();
  }

  return new Date(now.getTime() + 3600000).toISOString();
}

const nextRun = computeNextRun(schedule, tz);
const shouldDisable = maxRuns !== null && maxRuns !== undefined && runCount >= maxRuns;

await http({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/scheduled_actions?id=eq.${actionId}`,
  headers: {
    'apikey': SUPABASE_KEY,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  },
  body: {
    last_run: now.toISOString(),
    run_count: runCount,
    next_run: shouldDisable ? null : nextRun,
    enabled: !shouldDisable,
    updated_at: now.toISOString()
  }
});

return [{ json: { status: 'updated', actionId, runCount, nextRun: shouldDisable ? null : nextRun, disabled: shouldDisable } }];

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const BRIDGE_URL = 'http://file-bridge:3200';

// 1. Cleanup expired files on File Bridge
let bridgeResult = { cleaned: 0 };
try {
  bridgeResult = await helpers.httpRequest({
    method: 'DELETE',
    url: BRIDGE_URL + '/cleanup'
  });
} catch(e) {
  // File Bridge may not be running yet
}

// 2. Cleanup expired metadata in DB
let dbResult = null;
try {
  dbResult = await helpers.httpRequest({
    method: 'DELETE',
    url: SUPABASE_URL + '/rest/v1/file_refs?expires_at=lt.' + new Date().toISOString(),
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': 'Bearer ' + SUPABASE_KEY
    }
  });
} catch(e) {}

return [{ json: { bridge_cleaned: bridgeResult.cleaned || 0, db_cleanup: 'done' } }];

const raw = $input.first().json;
const instruction = raw.instruction || raw.message || '';
const mcpSkills = raw.mcp_skills || '';
const lang = raw.language || 'German';
const lastRun = raw.last_run || null;

const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'full', timeStyle: 'short' });

let timeContext = '';
if (lastRun) {
  const lastRunDate = new Date(lastRun);
  const lastRunStr = lastRunDate.toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'full', timeStyle: 'short' });
  timeContext = `\nIMPORTANT: Your last check was at ${lastRunStr}. ONLY report things that happened or arrived AFTER this time. Anything from before that time has already been reported — ignore it completely.\nIf there is nothing new since ${lastRunStr}, respond [SILENT].`;
} else {
  timeContext = `\nThis is the FIRST check. Report current state briefly if there is anything noteworthy.`;
}

const systemPrompt = `# BACKGROUND CHECKER
Current time: ${now}

You are a background checker executing a scheduled task silently.
Execute the instruction below using the available tools.
${timeContext}

RULES:
- ONLY use the tool(s) needed for the instruction. The instruction tells you which tool to use.
- Do NOT call tools on unrelated MCP servers. Do NOT explore or discover all available tools.
- Call the MCP Client ONCE with the correct server URL and tool name from the list below.
- NEVER send messages yourself (no Telegram, no notifications). Just return your findings as text.
- If the result shows something NEW (after your last check), describe it concisely in ${lang}.
- If there is NOTHING new or changed to report, respond with ONLY the exact text: [SILENT]
- Do NOT add greetings, commentary, or explanations when responding [SILENT].
- Ignore any part of the instruction that asks you to send notifications or messages — just report findings.
- Be concise when reporting changes — just the facts.
- Maximum 3 tool calls total. If you cannot complete the task in 3 calls, respond [SILENT].

${mcpSkills ? '# AVAILABLE MCP SKILLS (reference only — use ONLY what the instruction needs)\n' + mcpSkills : ''}`;

return [{
  json: {
    systemPrompt,
    userMessage: instruction
  }
}];

const qType = typeof query;
let url = '', method = 'GET', headers = {}, body = null;

if (qType === 'object' && query !== null) {
  url = query.url || '';
  method = (query.method || 'GET').toUpperCase();
  headers = query.headers || {};
  body = query.body || null;
} else if (qType === 'string') {
  try {
    const parsed = JSON.parse(query);
    url = parsed.url || '';
    method = (parsed.method || 'GET').toUpperCase();
    headers = parsed.headers || {};
    body = parsed.body || null;
  } catch(e) {
    url = query;
  }
}

if (!url) return 'Error: no URL provided';

try {
  const opts = { method, url, headers };
  if (body && method !== 'GET') {
    opts.body = typeof body === 'string' ? body : JSON.stringify(body);
    if (!headers['Content-Type']) headers['Content-Type'] = 'application/json';
  }
  const resp = await helpers.httpRequest(opts);
  const result = typeof resp === 'string' ? resp : JSON.stringify(resp);
  return result.length > 10000 ? result.substring(0, 10000) + '... (truncated)' : result;
} catch(e) {
  return 'HTTP Error: ' + e.message;
}

let input;
try { input = JSON.parse(query); } catch(e) { input = { q: query }; }
const q = input.q || input.query || query;
const result = await helpers.httpRequest({
  method: 'GET',
  url: `http://searxng:8080/search?q=${encodeURIComponent(q)}&format=json&language=de`,
  headers: { 'Accept': 'application/json' }
});
const hits = (result.results || []).slice(0, 5).map(r =>
  `${r.title}\n${r.url}\n${r.content || ''}`
).join('\n\n');
return hits || 'Keine Ergebnisse gefunden.';

const qType = typeof query;
let mcpUrl = '', toolName = '', args = {};

if (qType === 'object' && query !== null) {
  mcpUrl = query.mcp_url || '';
  toolName = query.tool_name || '';
  args = query.arguments || {};
} else if (qType === 'string') {
  try {
    const parsed = JSON.parse(query);
    mcpUrl = parsed.mcp_url || '';
    toolName = parsed.tool_name || '';
    args = parsed.arguments || {};
  } catch(e) {
    return 'Parse error: query=' + String(query).substring(0,200) + ' type=' + qType;
  }
} else {
  return 'Unexpected query type: ' + qType + ' value: ' + String(query).substring(0,200);
}

if (typeof args === 'string') try { args = JSON.parse(args); } catch(e) {}
if (!mcpUrl || !toolName) return 'Fehler: mcp_url=' + mcpUrl + ' tool_name=' + toolName;

function parseSSE(raw) {
  const str = String(raw);
  let lines = str.split('\n');
  if (lines.length <= 1) lines = str.split('\\n');
  for (let i = lines.length - 1; i >= 0; i--) {
    if (lines[i].startsWith('data: ')) {
      return JSON.parse(lines[i].substring(6));
    }
  }
  return null;
}

try {
  let authHeader = null;
  try {
    const row = await helpers.httpRequest({method:'GET',url:'{{SUPABASE_URL}}/rest/v1/mcp_registry?mcp_url=eq.'+encodeURIComponent(mcpUrl)+'&select=auth_type,auth_token&limit=1',headers:{apikey:'{{SUPABASE_SERVICE_KEY}}',Authorization:'Bearer {{SUPABASE_SERVICE_KEY}}'},json:true});
    if (row && row[0] && row[0].auth_type && row[0].auth_type !== 'none' && row[0].auth_token) {
      authHeader = row[0].auth_type === 'bearer' ? 'Bearer '+row[0].auth_token : row[0].auth_token;
    }
  } catch(e) {}

  const hdrs = {'Content-Type':'application/json','Accept':'application/json, text/event-stream'};
  if (authHeader) hdrs['Authorization'] = authHeader;

  const init = await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',id:1,method:'initialize',params:{protocolVersion:'2024-11-05',capabilities:{},clientInfo:{name:'n8n-claw-bg-checker',version:'1.0'}}}),
    returnFullResponse: true, encoding: 'utf-8', json: false
  });
  const sid = init.headers && init.headers['mcp-session-id'];
  if (sid) hdrs['mcp-session-id'] = sid;

  await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',method:'notifications/initialized'}),
    json: false
  });

  const listResp = await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',id:2,method:'tools/list',params:{}}),
    json: false
  });
  const listResult = parseSSE(listResp);
  let toolSchema = null;
  if (listResult && listResult.result && listResult.result.tools) {
    const tool = listResult.result.tools.find(t => t.name === toolName);
    if (tool && tool.inputSchema) toolSchema = tool.inputSchema;
  }

  function schemaHint(problem) {
    if (!toolSchema) return null;
    return 'Tool "' + toolName + '" call rejected: ' + problem +
      '\n\nCorrect input schema:\n' + JSON.stringify(toolSchema, null, 2) +
      '\n\nRetry the tool call with parameter names matching this schema exactly.';
  }

  if (toolSchema && toolSchema.properties) {
    const allowed = Object.keys(toolSchema.properties);
    const required = toolSchema.required || [];
    const unknown = Object.keys(args).filter(k => !allowed.includes(k));
    const missing = required.filter(r => args[r] === undefined || args[r] === null);
    if (unknown.length > 0 || missing.length > 0) {
      const problems = [];
      if (unknown.length > 0) problems.push('unknown args [' + unknown.join(', ') + ']');
      if (missing.length > 0) problems.push('missing required args [' + missing.join(', ') + ']');
      return schemaHint(problems.join('; '));
    }
  }

  const resp = await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',id:3,method:'tools/call',params:{name:toolName,arguments:args}}),
    returnFullResponse: true, encoding: 'utf-8', json: false
  });

  const result = parseSSE(resp.body || resp);
  if (!result) return 'MCP: Keine Daten. Response: ' + String(resp.body || resp).substring(0,500);
  if (result.error) {
    return schemaHint('server error: ' + JSON.stringify(result.error)) || ('MCP Error: ' + JSON.stringify(result.error));
  }
  if (result.result && result.result.isError) {
    const errText = (result.result.content && result.result.content[0] && result.result.content[0].text) || JSON.stringify(result.result);
    return schemaHint('tool returned error: ' + errText) || ('MCP Tool Error: ' + errText);
  }
  return result.result?.content?.[0]?.text || JSON.stringify(result.result);
} catch(e) {
  return 'MCP Error: ' + e.message;
}

