const stopWords = new Set(['build','baue','bau','erstelle','create','make','einen','eine','ein','der','die','das','und','or','the','a','an','with','mit','von','from','for','fuer','that','which','tool','mcp','server','named','namens','called','does','following','api','parameter','return','returns','using','http','get','post','json','format','data','request','requests','response','should','soll','dem','den','des','als','nimmt','ruft','auf','gibt','zurueck','titel','autor','isbn','buches','strukturiertes','antwort']);
const keywords = task.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 2 && !stopWords.has(w));

// Extract URLs mentioned in task to identify the target API domain
const urlMatches = task.match(/https?:\/\/([^\s\/\)]+)/g) || [];
const taskDomains = urlMatches.map(u => { try { return u.replace(/^https?:\/\//, '').split('/')[0].replace('www.',''); } catch(e) { return ''; } }).filter(Boolean);

const results = $json.results || [];
if (results.length === 0) return [{ json: { bestUrl: '', results, task } }];

const scored = results.map((r, i) => {
  const url = (r.url || '').toLowerCase();
  const title = (r.title || '').toLowerCase();
  const text = title + ' ' + url;
  let score = 0;

  // Keyword matches in title+url
  for (const kw of keywords) { if (text.includes(kw)) score += 2; }

  // Strong bonus: URL domain matches a domain mentioned in the task
  for (const d of taskDomains) { if (url.includes(d)) score += 10; }

  // Bonus for official API doc URL patterns
  if (/\/api\/|\/docs\/|\/dev\/|\/developer|\/reference|\/documentation/.test(url)) score += 5;

  // Penalty for generic sites
  if (/stackoverflow\.com|reddit\.com|learn\.microsoft\.com|medium\.com|w3tutorials|arcanecode|baeldung/.test(url)) score -= 5;

  // Slight position bonus
  score -= i * 0.1;
  return { url: r.url, title: r.title, score, index: i };
});

scored.sort((a, b) => b.score - a.score);
const best = scored[0];
return [{ json: { bestUrl: best.url || results[0]?.url || '', results, task, pickedIndex: best.index, pickedTitle: best.title, pickedScore: best.score } }];

